-- Split the former combined Automation & Custom Software practice.
-- Retain a neutral redirect for its old URL while moving legacy AI-specific URLs
-- to their closest new service pages.

begin;

update public.services
set slug = 'ai-automations', sort_order = 9, name = 'AI Automations', short_name = 'AI Automations', tagline = 'Put repeatable work on a reliable path.', summary = 'AI-assisted workflows and process automation for document handling, reporting, service operations and connected business systems.', intro = 'We map the process before automating it, then choose where rules-based automation or AI assistance is useful. Workflows include defined permissions, validation, logs, exception handling and human review where a decision needs it.', deliverables = '[{"title":"Process and suitability review","body":"Identify repeated tasks, data sources, decision points and failure cases before selecting an automation approach."},{"title":"Workflow automation","body":"Route requests, approvals, notifications and routine updates across the systems your team already uses."},{"title":"AI-assisted information handling","body":"Support document classification, extraction, summarisation and knowledge lookup with validation and human review built into the workflow."},{"title":"Integrations and controls","body":"Connect approved services through APIs with scoped access, execution logs, retry behaviour and clear exception paths."},{"title":"Testing and handover","body":"Test normal and failure cases, document the workflow and hand over operating guidance and ownership."}]'::jsonb, outcomes = array(select jsonb_array_elements_text('["Less time spent on repetitive process steps","Clear records of automated actions and exceptions","Human review retained for decisions that need it","Documented workflows with defined ownership"]'::jsonb))::text[], faqs = '[{"question":"What is AI automation?","answer":"It combines workflow rules and, where useful, AI assistance to handle repeatable work such as routing requests or extracting information from documents. Each use case is scoped to the process, data and systems involved."},{"question":"How do you keep automated workflows reliable?","answer":"We define permissions, test expected and failure cases, record actions and provide exception paths. Human approval stays in place where a decision should not run without review."},{"question":"Do we need a custom AI model?","answer":"Not necessarily. We first assess whether an approved existing model or rules-based workflow meets the need and data-handling requirements. Custom model work is considered only when there is a clear case for it."}]'::jsonb, related = array(select jsonb_array_elements_text('["application-development","managed-it","cloud-datacenter"]'::jsonb))::text[], figure = '{"seed":19,"label":"Automation flow","caption":"An AI-assisted workflow with scoped access, validation, a human review point, recorded actions and an exception path."}'::jsonb, seo_title = 'AI Automation Services', seo_description = 'Design controlled AI-assisted workflows and business process automation with integrations, human review and documented handover.'
where slug = 'automation-custom-software';

insert into public.services (slug, sort_order, name, short_name, tagline, summary, intro, deliverables, outcomes, faqs, related, figure, seo_title, seo_description, status, published_at)
values ('ai-automations', 9, 'AI Automations', 'AI Automations', 'Put repeatable work on a reliable path.', 'AI-assisted workflows and process automation for document handling, reporting, service operations and connected business systems.', 'We map the process before automating it, then choose where rules-based automation or AI assistance is useful. Workflows include defined permissions, validation, logs, exception handling and human review where a decision needs it.', '[{"title":"Process and suitability review","body":"Identify repeated tasks, data sources, decision points and failure cases before selecting an automation approach."},{"title":"Workflow automation","body":"Route requests, approvals, notifications and routine updates across the systems your team already uses."},{"title":"AI-assisted information handling","body":"Support document classification, extraction, summarisation and knowledge lookup with validation and human review built into the workflow."},{"title":"Integrations and controls","body":"Connect approved services through APIs with scoped access, execution logs, retry behaviour and clear exception paths."},{"title":"Testing and handover","body":"Test normal and failure cases, document the workflow and hand over operating guidance and ownership."}]'::jsonb, array(select jsonb_array_elements_text('["Less time spent on repetitive process steps","Clear records of automated actions and exceptions","Human review retained for decisions that need it","Documented workflows with defined ownership"]'::jsonb))::text[], '[{"question":"What is AI automation?","answer":"It combines workflow rules and, where useful, AI assistance to handle repeatable work such as routing requests or extracting information from documents. Each use case is scoped to the process, data and systems involved."},{"question":"How do you keep automated workflows reliable?","answer":"We define permissions, test expected and failure cases, record actions and provide exception paths. Human approval stays in place where a decision should not run without review."},{"question":"Do we need a custom AI model?","answer":"Not necessarily. We first assess whether an approved existing model or rules-based workflow meets the need and data-handling requirements. Custom model work is considered only when there is a clear case for it."}]'::jsonb, array(select jsonb_array_elements_text('["application-development","managed-it","cloud-datacenter"]'::jsonb))::text[], '{"seed":19,"label":"Automation flow","caption":"An AI-assisted workflow with scoped access, validation, a human review point, recorded actions and an exception path."}'::jsonb, 'AI Automation Services', 'Design controlled AI-assisted workflows and business process automation with integrations, human review and documented handover.', 'published', now())
on conflict (slug) do update set sort_order = 9, name = 'AI Automations', short_name = 'AI Automations', tagline = 'Put repeatable work on a reliable path.', summary = 'AI-assisted workflows and process automation for document handling, reporting, service operations and connected business systems.', intro = 'We map the process before automating it, then choose where rules-based automation or AI assistance is useful. Workflows include defined permissions, validation, logs, exception handling and human review where a decision needs it.', deliverables = '[{"title":"Process and suitability review","body":"Identify repeated tasks, data sources, decision points and failure cases before selecting an automation approach."},{"title":"Workflow automation","body":"Route requests, approvals, notifications and routine updates across the systems your team already uses."},{"title":"AI-assisted information handling","body":"Support document classification, extraction, summarisation and knowledge lookup with validation and human review built into the workflow."},{"title":"Integrations and controls","body":"Connect approved services through APIs with scoped access, execution logs, retry behaviour and clear exception paths."},{"title":"Testing and handover","body":"Test normal and failure cases, document the workflow and hand over operating guidance and ownership."}]'::jsonb, outcomes = array(select jsonb_array_elements_text('["Less time spent on repetitive process steps","Clear records of automated actions and exceptions","Human review retained for decisions that need it","Documented workflows with defined ownership"]'::jsonb))::text[], faqs = '[{"question":"What is AI automation?","answer":"It combines workflow rules and, where useful, AI assistance to handle repeatable work such as routing requests or extracting information from documents. Each use case is scoped to the process, data and systems involved."},{"question":"How do you keep automated workflows reliable?","answer":"We define permissions, test expected and failure cases, record actions and provide exception paths. Human approval stays in place where a decision should not run without review."},{"question":"Do we need a custom AI model?","answer":"Not necessarily. We first assess whether an approved existing model or rules-based workflow meets the need and data-handling requirements. Custom model work is considered only when there is a clear case for it."}]'::jsonb, related = array(select jsonb_array_elements_text('["application-development","managed-it","cloud-datacenter"]'::jsonb))::text[], figure = '{"seed":19,"label":"Automation flow","caption":"An AI-assisted workflow with scoped access, validation, a human review point, recorded actions and an exception path."}'::jsonb, seo_title = 'AI Automation Services', seo_description = 'Design controlled AI-assisted workflows and business process automation with integrations, human review and documented handover.';

insert into public.services (slug, sort_order, name, short_name, tagline, summary, intro, deliverables, outcomes, faqs, related, figure, seo_title, seo_description, status, published_at)
values ('application-development', 10, 'Application Development', 'Application Development', 'Build software around the work your team does.', 'Custom web applications, internal portals, dashboards and system integrations, delivered with tested code and a clear handover.', 'We develop web applications around the people, processes and systems that need to use them. The work covers requirements, interface design, application logic, data and API integration, testing, release and documentation, with security and maintainability considered throughout.', '[{"title":"Requirements and scope","body":"Agree user roles, core workflows, data needs, integrations and acceptance criteria before implementation begins."},{"title":"Web applications and portals","body":"Build internal tools, customer portals, operational dashboards and workflow applications to suit the agreed use case."},{"title":"APIs and data integration","body":"Connect existing systems through supported APIs and data interfaces, with validation and failure behaviour defined."},{"title":"Testing and release","body":"Test key workflows and edge cases, prepare a controlled release and document the deployment and rollback steps."},{"title":"Source code and handover","body":"Provide the agreed source code, setup instructions and technical documentation so the application can be maintained after delivery."}]'::jsonb, array(select jsonb_array_elements_text('["An application designed for agreed user workflows","Integrations with documented boundaries and failure handling","Tested release and deployment instructions","Source code and documentation for ongoing ownership"]'::jsonb))::text[], '[{"question":"What types of applications do you build?","answer":"We build web applications such as internal portals, operational dashboards, request and approval tools, and customer-facing interfaces. Scope is based on the users, process and systems involved."},{"question":"Can a new application connect to our existing systems?","answer":"Yes, when the systems expose a supported API or data interface. We confirm access, security and technical constraints during discovery and document them in the agreed scope."},{"question":"Who owns the application after handover?","answer":"The delivery includes the agreed source code and documentation. Hosting, third-party services, maintenance and support are defined separately so ongoing responsibilities are clear."}]'::jsonb, array(select jsonb_array_elements_text('["ai-automations","cybersecurity","cloud-datacenter"]'::jsonb))::text[], '{"seed":20,"label":"Application workflow","caption":"A custom application moving from user requirements and interface design through integration, testing, release and handover."}'::jsonb, 'Custom Application Development Services', 'Custom web application development for business portals, dashboards and connected workflows, with tested releases and source-code handover.', 'published', now())
on conflict (slug) do update set sort_order = 10, name = 'Application Development', short_name = 'Application Development', tagline = 'Build software around the work your team does.', summary = 'Custom web applications, internal portals, dashboards and system integrations, delivered with tested code and a clear handover.', intro = 'We develop web applications around the people, processes and systems that need to use them. The work covers requirements, interface design, application logic, data and API integration, testing, release and documentation, with security and maintainability considered throughout.', deliverables = '[{"title":"Requirements and scope","body":"Agree user roles, core workflows, data needs, integrations and acceptance criteria before implementation begins."},{"title":"Web applications and portals","body":"Build internal tools, customer portals, operational dashboards and workflow applications to suit the agreed use case."},{"title":"APIs and data integration","body":"Connect existing systems through supported APIs and data interfaces, with validation and failure behaviour defined."},{"title":"Testing and release","body":"Test key workflows and edge cases, prepare a controlled release and document the deployment and rollback steps."},{"title":"Source code and handover","body":"Provide the agreed source code, setup instructions and technical documentation so the application can be maintained after delivery."}]'::jsonb, outcomes = array(select jsonb_array_elements_text('["An application designed for agreed user workflows","Integrations with documented boundaries and failure handling","Tested release and deployment instructions","Source code and documentation for ongoing ownership"]'::jsonb))::text[], faqs = '[{"question":"What types of applications do you build?","answer":"We build web applications such as internal portals, operational dashboards, request and approval tools, and customer-facing interfaces. Scope is based on the users, process and systems involved."},{"question":"Can a new application connect to our existing systems?","answer":"Yes, when the systems expose a supported API or data interface. We confirm access, security and technical constraints during discovery and document them in the agreed scope."},{"question":"Who owns the application after handover?","answer":"The delivery includes the agreed source code and documentation. Hosting, third-party services, maintenance and support are defined separately so ongoing responsibilities are clear."}]'::jsonb, related = array(select jsonb_array_elements_text('["ai-automations","cybersecurity","cloud-datacenter"]'::jsonb))::text[], figure = '{"seed":20,"label":"Application workflow","caption":"A custom application moving from user requirements and interface design through integration, testing, release and handover."}'::jsonb, seo_title = 'Custom Application Development Services', seo_description = 'Custom web application development for business portals, dashboards and connected workflows, with tested releases and source-code handover.';

update public.services
set related = array_replace(related, 'automation-custom-software', 'ai-automations')
where 'automation-custom-software' = any(related);

update public.industries
set services = array(
  select distinct service_slug
  from unnest(
    array_replace(services, 'automation-custom-software', 'ai-automations')
    || array['application-development']::text[]
  ) as service_slug
)
where 'automation-custom-software' = any(services);

commit;
